INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(62162, 0, 0, 'Now, let us determine which knight will bring glory to its homeland!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216215'),
(62162, 1, 0, 'Onwards, to victory!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216216'),
(62452, 0, 0, 'Hopefully I don\'t get too much dust tossed my way.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6269001'),
(62452, 1, 0, 'Here it comes!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6269002'),
(62452, 2, 0, 'What a masterful display. A bliss to behold time and time again.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6269003'),
(62162, 2, 0, 'Now, fair spectators, a duel of monumental weight awaits us. Sir Lorenz of Theramore against the young and upcoming talent of Fritz of Kul Tiras!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216210'),
(62162, 3, 0, 'Incredible! Anyone present here at this tournament can vouch for the emotional investment brought into this duel. In the end, it is Sir Lorenz who shall be praised for this victory!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216217'),
(62162, 4, 0, 'Glory to Sir Lorenz of Theramore, victor to this knightly joust!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216222'),
(62162, 5, 0, 'Another joust awaits! A valiant duel between Sir Barnabas of Strom, a gilded veteran of old, and the equally skilled Lumiere of Dalaran!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216211'),
(62162, 6, 0, 'Such elegance! Lumiere effortlessly demonstrated that Dalaran should not be underestimated! A lesson Sir Barnabas felt hands-on!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216218'),
(62162, 7, 0, 'A toast to Lumiere of Dalaran, victor of this knightly joust!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216223'),
(62162, 8, 0, 'On to our next joust! To my left, a stout knight of our kingdom, Sir Reginald! To my right, from the far kingdom of Strom, Sir Rudolf!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216212'),
(62162, 9, 0, 'A clean strike! Sir Rudolf lies on the ground, defeated by the proud Sir Reginald!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216219'),
(62162, 10, 0, 'Glory to Sir Reginald, victor of this knightly joust!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216224'),
(62162, 11, 0, 'Silence, fair citizens, for a special bout is about to happen! Hailing under no flag and bearing no color, the Black Knight steps into the ring! His opponent: the courageous Halfar of Kul Tiras, breaker of tides and storms!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216213'),
(62162, 12, 0, 'What a merciless display! Call for the doctor, I\'m sure Sir Halfar sorely needs it! A gruesome reminder of how brutal these tournaments can become!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216220'),
(62162, 13, 0, 'The honor goes to the nameless Black Knight, victor of this knightly joust!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216225'),
(62162, 14, 0, 'The next joust begins! To my left, a brave contestant from the sea-faring nation of Theramore, Sir Ferdinand! To my right, a chivalrous mage and his steadfast steed, Estanor of Dalaran!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216214'),
(62162, 15, 0, 'Devastating! The might of Theramore was demonstrated once more on this day! Sir Estanor could not withstand Sir Ferdinand\'s mighty blow!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216221'),
(62162, 16, 0, 'Glory to Sir Ferdinand, victor of this knightly joust!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 6216226');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030589, '<A single spark could obliterate everything around.>', '<A single spark could obliterate everything around.>', 1, 0);
